PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS host_enquiries(id TEXT PRIMARY KEY,name TEXT NOT NULL,contact TEXT NOT NULL,area TEXT NOT NULL,space_type TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contact_messages(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS spaces(id TEXT PRIMARY KEY,host_email TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',town TEXT NOT NULL,neighbourhood TEXT NOT NULL DEFAULT '',space_type TEXT NOT NULL,size_label TEXT NOT NULL DEFAULT 'small',price_amount REAL NOT NULL,price_period TEXT NOT NULL DEFAULT 'month',currency TEXT NOT NULL DEFAULT 'KES',access_summary TEXT NOT NULL DEFAULT '',security_summary TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','pending_review','published','rejected','suspended')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_spaces_public ON spaces(status,town,space_type,created_at);
CREATE TABLE IF NOT EXISTS space_photos(id TEXT PRIMARY KEY,space_id TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE,r2_key TEXT NOT NULL,is_cover INTEGER NOT NULL DEFAULT 0,alt_text TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bookings(id TEXT PRIMARY KEY,space_id TEXT NOT NULL REFERENCES spaces(id),renter_email TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,total_amount REAL NOT NULL,currency TEXT NOT NULL DEFAULT 'KES',status TEXT NOT NULL DEFAULT 'requested',payment_reference TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_email TEXT NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at);
